sys_script_include.script:
var DayOneReadinessAjax = Class.create();
DayOneReadinessAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getPlans: function() {
        var stateFilter = this.getParameter('sysparm_state');
        var gr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');

        if (stateFilter) {
            gr.addQuery('state', stateFilter);
        }

        gr.query();

        var plans = [];
        while (gr.next()) {
            plans.push({
                sys_id: gr.getUniqueValue(),
                number: gr.getValue('number'),
                employee_name: gr.getValue('employee_name'),
                employee_id: gr.getValue('employee_id'),
                role: gr.getValue('role'),
                department: gr.getValue('department'),
                location: gr.getValue('location'),
                joining_date: gr.getValue('joining_date'),
                readiness_score: gr.getValue('readiness_score'),
                readiness_status: gr.getValue('readiness_status'),
                forecast_status: gr.getValue('forecast_status'),
                state: gr.getValue('state')
            });
        }

        return JSON.stringify(plans);
    },

    getPlanDetails: function() {
        var planId = this.getParameter('sysparm_plan_id');
        var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');

        if (!planGr.get(planId)) {
            return JSON.stringify({ error: 'Plan not found' });
        }

        var plan = {
            sys_id: planGr.getUniqueValue(),
            number: planGr.getValue('number'),
            employee_name: planGr.getValue('employee_name'),
            employee_id: planGr.getValue('employee_id'),
            role: planGr.getValue('role'),
            department: planGr.getValue('department'),
            location: planGr.getValue('location'),
            joining_date: planGr.getValue('joining_date'),
            manager: planGr.getValue('manager'),
            coordinator: planGr.getValue('coordinator'),
            readiness_score: planGr.getValue('readiness_score'),
            readiness_status: planGr.getValue('readiness_status'),
            forecast_status: planGr.getValue('forecast_status'),
            readiness_threshold: planGr.getValue('readiness_threshold'),
            state: planGr.getValue('state'),
            notes: planGr.getValue('notes'),
            tasks: []
        };

        var taskGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
        taskGr.addQuery('plan', planId);
        taskGr.query();

        while (taskGr.next()) {
            plan.tasks.push({
                sys_id: taskGr.getUniqueValue(),
                task_name: taskGr.getValue('task_name'),
                department: taskGr.getValue('department'),
                mandatory: taskGr.getValue('mandatory'),
                due_date: taskGr.getValue('due_date'),
                est_remaining_days: taskGr.getValue('est_remaining_days'),
                task_state: taskGr.getValue('task_state'),
                evidence_verified: taskGr.getValue('evidence_verified'),
                assigned_to: taskGr.getValue('assigned_to'),
                description: taskGr.getValue('description')
            });
        }

        return JSON.stringify(plan);
    },

    recalculateReadiness: function() {
        var planId = this.getParameter('sysparm_plan_id');
        var engine = new DayOneReadinessEngine(planId);
        engine.recalculate();

        // Return updated plan data
        var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
        if (planGr.get(planId)) {
            return JSON.stringify({
                sys_id: planGr.getUniqueValue(),
                readiness_score: planGr.getValue('readiness_score'),
                readiness_status: planGr.getValue('readiness_status'),
                forecast_status: planGr.getValue('forecast_status')
            });
        }

        return JSON.stringify({ error: 'Plan not found after recalculation' });
    },

    triggerRecovery: function() {
        var planId = this.getParameter('sysparm_plan_id');
        var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');

        if (planGr.get(planId)) {
            planGr.setValue('readiness_status', 'blocked');
            planGr.update();
            return JSON.stringify({ success: true, message: 'Recovery triggered for plan ' + planId });
        }

        return JSON.stringify({ success: false, message: 'Plan not found' });
    },

    type: 'DayOneReadinessAjax'
});
